defmodule JoobQ.RateLimitsTest do
  use ExUnit.Case, async: true

  alias JoobQ.RateLimits

  test "the body names the key, the limit and the window" do
    assert RateLimits.body("tenant-1", 10, 60_000) ==
             %{"key" => "tenant-1", "limit" => 10, "period_ms" => 60_000}
  end

  test "a wrong argument is named, never its value" do
    for {args, name} <- [
          {["", 1, 1], :key},
          {[String.duplicate("k", 201), 1, 1], :key},
          {["k", 0, 1], :limit},
          {["k", 1, 86_400_001], :period_ms},
          {["k", 1.5, 1], :limit}
        ] do
      assert_raise ArgumentError, ~r/#{inspect(name)}/, fn -> apply(RateLimits, :body, args) end
    end

    error = assert_raise ArgumentError, fn -> RateLimits.body(%{"t" => "hunter2"}, 1, 1) end
    refute error.message =~ "hunter2"
    assert_raise ArgumentError, ~r/:other/, fn -> JoobQ.rate_limit("k", 1, 1, other: 1) end
  end
end
